<!DOCTYPE html>
<html lang="pt-BR">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Criar empresa · FiscalFlow</title>
    <script src="https://cdn.tailwindcss.com"></script>
    <script defer src="https://cdn.jsdelivr.net/npm/alpinejs@3.x.x/dist/cdn.min.js"></script>
</head>
<body class="min-h-screen bg-slate-950 text-slate-900 antialiased">
    <main class="grid min-h-screen lg:grid-cols-[1.05fr_0.95fr]"><section class="relative hidden overflow-hidden bg-gradient-to-br from-slate-950 via-slate-900 to-blue-950 p-12 text-white lg:flex lg:flex-col lg:justify-between"><div class="relative flex items-center gap-3"><div class="flex h-11 w-11 items-center justify-center rounded-xl bg-blue-600 text-xl font-bold">F</div><span class="text-lg font-semibold">FiscalFlow</span></div><div class="relative max-w-xl"><p class="mb-5 text-sm font-semibold uppercase tracking-[0.2em] text-blue-300">SaaS fiscal</p><h1 class="text-5xl font-bold leading-tight tracking-tight">Sua operação fiscal pronta para crescer.</h1><p class="mt-6 text-lg leading-8 text-slate-300">Cadastre sua empresa e organize NF-e, produtos, clientes e certificados.</p></div><p class="relative text-sm text-slate-500">Cadastro seguro · FiscalFlow</p></section><section class="flex items-center justify-center bg-slate-50 px-6 py-10 sm:px-10"><div class="w-full max-w-xl" x-data="registerForm()"><div class="rounded-2xl border border-slate-200 bg-white p-7 shadow-sm sm:p-9"><p class="text-sm font-semibold text-blue-600">Comece agora</p><h2 class="mt-2 text-2xl font-bold tracking-tight text-slate-950">Crie sua empresa</h2><p class="mt-2 text-sm text-slate-500">Você será o Administrador inicial da conta.</p><form class="mt-8 space-y-5" @submit.prevent="submit"><div class="border-b border-slate-100 pb-5"><p class="text-xs font-bold uppercase tracking-wider text-slate-400">Dados da empresa</p><label class="mt-4 block"><span class="label">CNPJ</span><input x-model="form.cnpj" @input="formatCnpj" @input.debounce.500ms="lookupCnpj" inputmode="numeric" maxlength="18" required class="field" placeholder="00.000.000/0000-00"><small x-show="loadingCnpj" class="mt-1 block text-xs text-blue-600">Consultando CNPJ...</small></label><label class="mt-4 block"><span class="label">Razão social</span><input x-model="form.razao_social" required class="field" placeholder="Será preenchida pelo CNPJ"></label></div><div><p class="text-xs font-bold uppercase tracking-wider text-slate-400">Administrador da conta</p><label class="mt-4 block"><span class="label">Nome completo</span><input x-model="form.name" required class="field" placeholder="Nome do responsável"></label><label class="mt-4 block"><span class="label">E-mail</span><input x-model="form.email" type="email" autocomplete="email" required class="field" placeholder="voce@empresa.com.br"></label><div class="mt-4 grid gap-4 sm:grid-cols-2"><label><span class="label">Senha</span><input x-model="form.password" type="password" autocomplete="new-password" required class="field" placeholder="Mínimo de 8 caracteres"></label><label><span class="label">Confirmar senha</span><input x-model="form.password_confirmation" type="password" autocomplete="new-password" required class="field"></label></div><small class="mt-1 block text-xs text-slate-500">Use maiúscula, minúscula, número e símbolo.</small></div><div x-show="error" x-cloak class="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700" x-text="error"></div><button type="submit" :disabled="loading" class="w-full rounded-xl bg-blue-600 px-4 py-3 text-sm font-semibold text-white hover:bg-blue-700 disabled:opacity-70" x-text="loading ? 'Criando sua conta...' : 'Criar empresa e acessar'"></button></form></div><p class="mt-6 text-center text-sm text-slate-500">Já possui uma conta? <a href="{{ route('login') }}" class="font-semibold text-blue-600">Entrar</a></p></div></section></main>
    <script>
        function registerForm() { return { form: { cnpj: '', razao_social: '', name: '', email: '', password: '', password_confirmation: '' }, loading: false, loadingCnpj: false, error: '', formatCnpj() { const digits = this.form.cnpj.replace(/\D/g, '').slice(0, 14); this.form.cnpj = digits.replace(/^(\d{2})(\d)/, '$1.$2').replace(/^(\d{2})\.(\d{3})(\d)/, '$1.$2.$3').replace(/^(\d{2})\.(\d{3})\.(\d{3})(\d)/, '$1.$2.$3/$4').replace(/^(\d{2})\.(\d{3})\.(\d{3})\/(\d{4})(\d)/, '$1.$2.$3/$4-$5'); }, async lookupCnpj() { const cnpj = this.form.cnpj.replace(/\D/g, ''); if (cnpj.length !== 14) return; this.loadingCnpj = true; this.error = ''; try { const response = await fetch('https://brasilapi.com.br/api/cnpj/v1/' + cnpj); if (!response.ok) throw new Error('CNPJ não encontrado na base pública.'); const data = await response.json(); this.form.razao_social = data.razao_social || data.nome_fantasia || ''; } catch (error) { this.error = error.message; } finally { this.loadingCnpj = false; } }, async submit() { this.loading = true; this.error = ''; try { const response = await fetch('/api/auth/register', { method: 'POST', headers: { 'Content-Type': 'application/json', Accept: 'application/json' }, body: JSON.stringify(this.form) }); const data = await response.json(); if (!response.ok) throw new Error(data.message || 'Não foi possível concluir o cadastro.'); localStorage.setItem('nfe_token', data.access_token); localStorage.setItem('nfe_user', JSON.stringify(data.user)); window.location.href = '/dashboard'; } catch (error) { this.error = error.message; } finally { this.loading = false; } } }; }
    </script><style>.label{display:block;font-size:.75rem;font-weight:600;color:#475569}.field{margin-top:.5rem;display:block;width:100%;border:1px solid #cbd5e1;border-radius:0;background:#fff;padding:.75rem 1rem;font-size:.875rem;outline:none}.field:focus{border-color:#3b82f6;box-shadow:0 0 0 4px rgb(59 130 246/.12)}</style>
</body>
</html>
